"""Set public build options. Private identity is generated by the camera at first boot."""
from datetime import datetime,timedelta,timezone
from pathlib import Path
import argparse,json,re

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--hostname',default='a800-local')
    p.add_argument('--ap-ssid',default='a800Local')
    p.add_argument('--ap-password',default='localcam-2026')
    args=p.parse_args()
    if not re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,29}[a-z0-9])?',args.hostname):p.error('Hostname must be a lowercase DNS label, maximum 31 characters')
    if not 1<=len(args.ap_ssid.encode())<=32:p.error('AP SSID must contain 1..32 UTF-8 bytes')
    if not 8<=len(args.ap_password)<=63 or not args.ap_password.isascii():p.error('AP password must contain 8..63 ASCII characters')
    now=datetime.now(timezone.utc)
    settings={'LC_HOSTNAME':args.hostname,'LC_SETUP_SSID':args.ap_ssid,'LC_SETUP_PASSWORD':args.ap_password,
              'LC_CERT_NOT_BEFORE':(now-timedelta(days=1)).strftime('%Y%m%d000000'),
              'LC_CERT_NOT_AFTER':(now+timedelta(days=3650)).strftime('%Y%m%d000000')}
    out=Path(__file__).resolve().parents[1]/'build/generated';out.mkdir(parents=True,exist_ok=True)
    (out/'localcam_device.h').write_text('/* Build options, including setup AP credentials. No device TLS/account keys. */\n'+
        ''.join(f'#define {k} {json.dumps(v)}\n' for k,v in settings.items()))
    print('Build options saved. Camera identity will be generated on the device.')

if __name__=='__main__':main()
